package sortutils

import "sort"

// BUG: sorts ascending by length instead of descending
func SortByLen(strs []string) []string {
	out := make([]string, len(strs))
	copy(out, strs)
	sort.Slice(out, func(i, j int) bool {
		return len(out[i]) < len(out[j])
	})
	return out
}

// BUG: returns sorted slice without removing duplicates
func SortUniq(nums []int) []int {
	out := make([]int, len(nums))
	copy(out, nums)
	sort.Ints(out)
	return out
}

// BUG: sorts ascending instead of descending
func SortDesc(nums []int) []int {
	out := make([]int, len(nums))
	copy(out, nums)
	sort.Ints(out)
	return out
}

package sortutils

import "testing"

func TestSortByLen(t *testing.T) {
	result := SortByLen([]string{"a", "ccc", "bb"})
	if result[0] != "ccc" || result[1] != "bb" || result[2] != "a" {
		t.Fatalf("want [ccc bb a], got %v", result)
	}
}

func TestSortUniq(t *testing.T) {
	result := SortUniq([]int{3, 1, 2, 1, 3})
	if len(result) != 3 || result[0] != 1 || result[1] != 2 || result[2] != 3 {
		t.Fatalf("want [1 2 3], got %v", result)
	}
}

func TestSortDesc(t *testing.T) {
	result := SortDesc([]int{3, 1, 4, 1, 5})
	if result[0] != 5 || result[1] != 4 || result[2] != 3 {
		t.Fatalf("want [5 4 3 1 1], got %v", result)
	}
}

func TestSortUniqEmpty(t *testing.T) {
	result := SortUniq([]int{})
	if len(result) != 0 {
		t.Fatalf("want empty, got %v", result)
	}
}

func TestSortDescSingle(t *testing.T) {
	result := SortDesc([]int{42})
	if len(result) != 1 || result[0] != 42 {
		t.Fatalf("want [42], got %v", result)
	}
}
